int binarySearch(int arr[], int size, int target) {
    int left = 0;
    int right = size; // Common mistake: should be size - 1 for 0-indexed array
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (arr[mid] == target) {
            return mid;
        } else if (arr[mid] < target) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    return -1;
}
